		this.percent = ( event?.target?.valueAsNumber / this.max * 100 );
	}
}

Radio Group.sourceCode:
import {
	Component, Input, ContentChildren,
	QueryList, AfterContentInit, ViewEncapsulation,
	forwardRef, SimpleChanges, OnChanges,
	HostListener, Output, EventEmitter,
	ChangeDetectionStrategy, HostBinding
} from '@angular/core';
import { FormControl, ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { startWith, takeUntil } from 'rxjs/operators';
import _ from 'lodash';

import { Unsubscriber, CoerceBoolean, DefaultValue, untilCmpDestroyed } from '@core';
import { NgcRadioComponent } from '../ngc-radio/ngc-radio.component';

export type NgcRadioGroupDirection = 'vertical' | 'horizontal';

@Unsubscriber()
@Component({
	selector		: 'ngc-radio-group',
	templateUrl		: './ngc-radio-group.html',
	styleUrls		: [ './ngc-radio-group.scss' ],
	host			: { class: 'ngc-radio-group' },
	encapsulation	: ViewEncapsulation.None,
	changeDetection	: ChangeDetectionStrategy.OnPush,
	providers: [{
		provide		: NG_VALUE_ACCESSOR,
		useExisting	: forwardRef( () => NgcRadioGroupComponent ),
		multi		: true,
	}],
})
export class NgcRadioGroupComponent implements OnChanges, AfterContentInit, ControlValueAccessor {

	@HostBinding( 'class.ngc-radio-group--vertical' )
	get classVertical(): boolean { return this.direction === 'vertical'; }

	@HostBinding( 'class.ngc-radio-group--horizontal' )
	get classHorizontal(): boolean { return this.direction === 'horizontal'; }

	@ContentChildren( NgcRadioComponent, { descendants: true } ) public radioList: QueryList<NgcRadioComponent>;

	@Input() public ngModel: any;
	@Input() public label: any;
	@Input() public disableControl: boolean;
	@Input() @CoerceBoolean() public disabled: boolean;
	@Input() @CoerceBoolean() public readonly: boolean;
	@Input() @CoerceBoolean() public required: boolean;
	@Input() @DefaultValue() public direction: NgcRadioGroupDirection = 'vertical';
	@Input() public formControl: FormControl;

	@Output() public ngModelChange: EventEmitter<any> = new EventEmitter<any>();

	private _innerValue: any;

	@HostListener( 'click', [ '$event' ] )
	public triggerClick( event: MouseEvent ) {
		if ( this.disabled || this.disableControl || this.readonly || !this.formControl ) return;

		event.stopPropagation();
		this.formControl.markAsTouched();
	}

	/**
	 * @constructor
	 * @param {any} value
	 */
	public writeValue( value: any ) {
		if ( value === this._innerValue ) return;

		this._innerValue = value;
	}

	/**
	 * @constructor
	 * @param {Function} fn
	 */
	public registerOnChange( fn: Function ) {
		this._onChangeCallback = fn;
	}

	/**
	 * @constructor
	 * @param {Function} fn
	 */
	public registerOnTouched( fn: Function ) {
		this._onTouchedCallback = fn;
	}

	/**
	 * @constructor
	 * @param {SimpleChanges} changes
	 */
	ngOnChanges( changes: SimpleChanges ) {
		if ( !changes.ngModel ) return;

		_.forEach( this.radioList?.toArray(), ( item: NgcRadioComponent ) => {
			item.checked = item.value !== undefined && item.value === this.ngModel;
		} );
	}

	/**
	 * @constructor
	 */
	ngAfterContentInit() {
		this.radioList
		.changes
		.pipe(
			startWith( this.radioList ),
			untilCmpDestroyed( this )
		)
		.subscribe( ( items: QueryList<NgcRadioComponent> ) => {
			const itemArr: NgcRadioComponent[] = items?.toArray();

			_.forEach( itemArr, ( item: NgcRadioComponent, index: number ) => {
				item.checked = item.value !== undefined && item.value === this.ngModel;
				item.disabled = item.disabled || this.disabled || this.disableControl;
				item.readonly = item.readonly || this.readonly;

				item
				.checkedChange
				.pipe(
					takeUntil( this.radioList.changes ),
					untilCmpDestroyed( this )
				)
				.subscribe( ( checked: boolean ) => {
					if ( !checked ) {
						item.checked = true;
						return;
					}

					this._innerValue = this.ngModel = item.value;

					_.forEach( itemArr, ( _item: NgcRadioComponent, _index: number ) => {
						_item.checked = index === _index;
					} );
					this._onTouchedCallback();
					this._onChangeCallback( this._innerValue );
				} );
			} );
		} );
	}

	private _onTouchedCallback: Function = () => {};
	private _onChangeCallback: Function = ( _v: any ) => {};

}

Search Box.sourceCode:
import {
	Component, ViewEncapsulation, Input,
	Output, EventEmitter, OnChanges,
	SimpleChanges, ChangeDetectionStrategy, ElementRef,
	ViewChild, OnDestroy, ChangeDetectorRef,
	TemplateRef
} from '@angular/core';
import { Subject, isObservable } from 'rxjs';
import { debounceTime, distinctUntilChanged } from 'rxjs/operators';
import { FormControl } from '@angular/forms';
import _ from 'lodash';

import {
	Unsubscriber, DefaultValue, CoerceBoolean,
	CoerceNumber, untilCmpDestroyed, INotFoundData
} from '@core';
import { CONSTANT as APP_CONSTANT } from '@resources';

import { NgcIFormFieldAppearance, NgcIFormFieldErrorDisplayMode } from '../ngc-form-field';
import { NgcMenuTriggerForDirective } from '../ngc-menu';

@Unsubscriber()
@Component({
	selector		: 'ngc-search-box',
	templateUrl		: './ngc-search-box.html',
	styleUrls		: [ './ngc-search-box.scss' ],
	host			: { class: 'ngc-search-box' },
	encapsulation	: ViewEncapsulation.None,
	changeDetection	: ChangeDetectionStrategy.OnPush,
})
export class NgcSearchBoxComponent implements OnChanges, OnDestroy {

	@ViewChild( NgcMenuTriggerForDirective, { static: true } ) public menuTrigger: NgcMenuTriggerForDirective;
	@ViewChild( 'notFoundTemplate', { static: true } ) public notFoundTemplate: TemplateRef<any>;

	@Input() public data: any[];
	@Input() public suggestion: any;
	@Input() public ngModel: string;
	@Input() public name: string;
	@Input() public label: string;
	@Input() public placeholder: string;
	@Input() @DefaultValue() public prefixIcon: string = 'search';
	@Input() public suffixIcon: string;
	@Input() @DefaultValue() public searchKey: string = 'name';
	@Input() @DefaultValue() public fieldName: string = 'name';
	@Input() @DefaultValue() public fieldDescription: string = 'description';
	@Input() @DefaultValue() public fieldImage: string = 'image';
	@Input() @DefaultValue() public fieldAvatar: string = 'avatar';
	@Input() @DefaultValue() @CoerceNumber() public itemSize: number = 54;
	@Input() @DefaultValue() @CoerceNumber() public debounceTime: number = 400;
	@Input() @DefaultValue() @CoerceBoolean() public trim: boolean = true;
	@Input() @CoerceBoolean() public displayNotFound: boolean;
	@Input() public disableControl: boolean;
	@Input() @CoerceBoolean() public disabled: boolean;
	@Input() @CoerceBoolean() public readonly: boolean;
	@Input() @CoerceBoolean() public required: boolean;
	@Input() @CoerceBoolean() public autoFocusOn: boolean;
	@Input() @CoerceBoolean() public autoReset: boolean;
	@Input() public notFoundData: INotFoundData;
	@Input() public formControl: FormControl;
	@Input() @DefaultValue() public appearance: NgcIFormFieldAppearance = 'default';
	@Input() @DefaultValue() public errorDisplayMode: NgcIFormFieldErrorDisplayMode = 'default';
	@Input() public filterPredicate: ( data: any, searchQuery: string, searchKey?: string ) => boolean;

	@Output() public ngModelChange: EventEmitter<string> = new EventEmitter<string>();
	@Output() public searching: EventEmitter<string> = new EventEmitter<string>();
	@Output() public cleared: EventEmitter<Event> = new EventEmitter<Event>();
	@Output() public filtered: EventEmitter<any[]> = new EventEmitter<any[]>();
	@Output() public suggested: EventEmitter<any> = new EventEmitter<any>();
	@Output() public prefixIconClicked: EventEmitter<void> = new EventEmitter<void>();
	@Output() public suffixIconClicked: EventEmitter<void> = new EventEmitter<void>();
	@Output() public input: EventEmitter<Event> = new EventEmitter<Event>();
	@Output() public focus: EventEmitter<Event> = new EventEmitter<Event>();
	@Output() public blur: EventEmitter<Event> = new EventEmitter<Event>();

	public searchQuery: string;
	public focusing: boolean;
	public focusIndex: number = 0;
	public filteredData: any[];
	public suggestionData: any[];

	private _searchUpdated$: Subject<string> = new Subject<string>();

	get useVirtualScroll(): boolean {
		return this.suggestionData?.length >= APP_CONSTANT.USE_VIRTUAL_SCROLL_WITH;
	}

	/**
	 * @constructor
	 * @param {ElementRef} elementRef
	 * @param {ChangeDetectorRef} _cdRef
	 */
	constructor( public elementRef: ElementRef, private _cdRef: ChangeDetectorRef ) {
		this._searchUpdated$
		.pipe(
			debounceTime( this.debounceTime ),
			distinctUntilChanged(),
			untilCmpDestroyed( this )
		)
		.subscribe( ( value: string ) => {
			this.searching.emit( value );

			// Start filter
			this._filter();

			// Start suggest
			this.focusing && this._suggest();
		} );
	}

	/**
	 * @constructor
	 */
	ngOnDestroy() {
		this._searchUpdated$.complete();
	}

	/**
	 * @constructor
	 * @param {SimpleChanges} changes
	 */
	ngOnChanges( changes: SimpleChanges ) {
		changes.data && this._filter();
		changes.ngModel && this.ngModel !== undefined && this.onSearch( this.ngModel );
	}

	/**
	 * @param {string} searchQuery
	 * @return {void}
	 */
	public onSearch( searchQuery: string ) {
		this.searchQuery = searchQuery || '';

		this._searchUpdated$.next( this.searchQuery );
	}

	/**
	 * @param {Event} event
	 * @return {void}
	 */
	public onClear( event: Event ) {
		this.clear( event );
	}

	/**
	 * @param {Event} event
	 * @return {void}
	 */
	public onInput( event: Event ) {
		this.input.emit( event );
	}

	/**
	 * @param {Event} event
	 * @return {void}
	 */
	public onFocus( event: Event ) {
		this.focusing = true;

		this.focus.emit( event );
	}

	/**
	 * @param {Event} event
	 * @return {void}
	 */
	public onBlur( event: Event ) {
		this.focusing = false;

		this.blur.emit( event );
	}

	/**
	 * @param {Event} event
	 * @return {void}
	 */
	public clear( event?: Event ) {
		this.ngModel = this.searchQuery = '';

		this._searchUpdated$.next( this.searchQuery );
		this.ngModelChange.emit( this.ngModel );
		this.filtered.emit( this.data );
		this.cleared.emit( event );
		this._cdRef.markForCheck();
	}

	/**
	 * @param {Event} event
	 * @param {number} index
	 * @return {void}
	 */
	public chooseSuggestItem( event: Event, index: number ) {
		if ( !this.suggestionData ) return;

		const item: any = this.suggestionData[ index ];

		if ( !item ) return;

		event.stopPropagation();
		event.preventDefault();

		this.ngModel = _.get( item, this.searchKey || this.fieldName );

		this._searchUpdated$.next( this.searchQuery );
		this.ngModelChange.emit( this.ngModel );
		this.suggested.emit( item );
		this.menuTrigger.close();
	}

	/**
	 * @param {Event} event
	 * @return {void}
	 */
	public focusPreviousSuggestItem( event: Event ) {
		if ( !this.suggestionData ) return;

		event.stopPropagation();
		event.preventDefault();

		this.focusIndex = this.focusIndex > 0 ? this.focusIndex - 1 : 0;
	}

	/**
	 * @param {Event} event
	 * @return {void}
	 */
	public focusNextSuggestItem( event: Event ) {
		if ( !this.suggestionData ) return;

		event.stopPropagation();
		event.preventDefault();

		const length: number = this.suggestionData?.length - 1;

		this.focusIndex = this.focusIndex < length ? this.focusIndex + 1 : length;
	}

	/**
	 * @return {void}
	 */
	private _toggleMenu() {
		this.searchQuery && this.suggestionData?.length
			? this.menuTrigger.open()
			: this.menuTrigger.close();
	}

	/**
	 * @return {void}
	 */
	private _filter() {
		if ( this.searchQuery ) {
			this.filteredData = _.filter( this.data, this._filterPredicate.bind( this ) );
		} else {
			this.filteredData = _.clone( this.data );
		}

		this.filtered.emit( this.filteredData );
		this._cdRef.markForCheck();
	}

	/**
	 * @return {void}
	 */
	private _suggest() {
		if ( !this.suggestion ) return;

		const suggestion: any = this.suggestion( this.searchQuery );
		console.log({suggestion}, 'searchQuery:', this.searchQuery, 'menuTrigger:', this.menuTrigger);
		if ( isObservable( suggestion ) ) {
			suggestion
			.pipe( untilCmpDestroyed( this ) )
			.subscribe( ( data: any[] ) => {
				this.suggestionData = data;
				console.log('async suggestionData updated:', this.suggestionData);
				this._toggleMenu();
				this._cdRef.markForCheck();
			} );
			return;
		}

		this.suggestionData = suggestion;
		console.log('sync suggestionData updated:', this.suggestionData);
		this._toggleMenu();
		this._cdRef.markForCheck();
	}

	/**
	 * @param {any} item
	 * @return {boolean}
	 */
	private _filterPredicate( item: any ): boolean {
		return _.isFunction( this.filterPredicate )
			? this.filterPredicate( item, this.searchQuery, this.searchKey )
			:_.search(
				this.searchKey ? _.get( item, this.searchKey ) : item,
				this.searchQuery
			);
	};

}

